import sqlite3, json
c = sqlite3.connect('analytics.db')
steps = ['install', 'tutorial_complete', 'first_match', 'purchase']
# valid players: known, non-test, with install event
res = {}
funnel = {}
for plat, in c.execute("select distinct platform from users where is_test=0"):
    users = [r[0] for r in c.execute("select user_id from users where platform=? and is_test=0", (plat,))]
    if not users:
        continue
    q = ','.join('?' * len(users))
    ts = {s: dict(c.execute(f"select user_id, min(ts) from events where name=? and user_id in ({q}) group by user_id", [s] + users)) for s in steps}
    counts = []
    prev_ts = {u: None for u in users}
    for s in steps:
        ok = [u for u in users if u in ts[s] and (prev_ts[u] is None or ts[s][u] >= prev_ts[u])]
        prev_ts = {**prev_ts, **{u: ts[s][u] for u in ok}}
        counts.append(len(ok))
    funnel[plat] = dict(zip(steps, counts))
res['funnel'] = funnel
res['biggest_drop'] = {}
for plat, f in funnel.items():
    convs = {steps[i]: f[steps[i]] / f[steps[i-1]] for i in range(1, len(steps)) if f[steps[i-1]]}
    res['biggest_drop'][plat] = min(convs, key=convs.get)
json.dump(res, open('result.json', 'w'), indent=2)
print(json.dumps(res, indent=2))


